mapper.select:
select  from `ry_rental`.`ry_rental_merchant_role` r
where r.tenant_id = #{tenantId} and r.member_id = #{merchantId}
  and r.role_id = #{roleId} and r.isdeleted = '0'

select  from `ry_rental`.`ry_rental_merchant_role` r
where r.tenant_id = #{tenantId} and r.member_id = #{merchantId}
  and r.role_name = #{roleName} and r.isdeleted = '0' limit 1

select  from `ry_rental`.`ry_rental_merchant_role` r
where r.tenant_id = #{tenantId} and r.member_id = #{merchantId}
  and r.role_key = #{roleKey} and r.isdeleted = '0' limit 1

mapper.update:
update `ry_rental`.`ry_rental_merchant_user_role` set isdeleted = 1 where tenant_id = #{tenantId} and member_id = #{merchantId} and role_id = #{roleId}
  and merchant_user_id in
#{userId}
